#include <bits/stdc++.h>
using namespace std;

struct Scan {
    std::stringstream ss;
    std::string line;
    std::istream& in;
    Scan(std::istream& input = std::cin) : in(input) {}
    std::string next() {
        while (!(ss >> std::ws), !(ss >> std::ws) || ss.eof()) {
            if (!std::getline(in, line)) return "";
            ss.clear();
            ss.str(line);
        }
        std::string token;
        ss >> token;
        return token;
    }
    int nextInt() { return std::stoi(next()); }
    long long nextLong() { return std::stoll(next()); }
    double nextDouble() { return std::stod(next()); }
    std::string nextLine() {
        if (ss.rdbuf()->in_avail() == 0) {
            std::getline(in, line);
            return line;
        } else {
            std::string rest;
            std::getline(ss, rest);
            return rest;
        }
    }
};

const long long MOD = 998244353LL;
const int asz = 200005;
long long f[asz];

long long BigMod(long long a, long long b, long long m) {
    long long res = 1LL;
    a %= m;
    while (b > 0) {
        if (b & 1) res = (res * a) % m;
        a = (a * a) % m;
        b >>= 1;
    }
    return res;
}

long long C(int n, int k) {
    if (k > n) return 0LL;
    return f[n] * BigMod(f[k], MOD - 2, MOD) % MOD * BigMod(f[n - k], MOD - 2, MOD) % MOD;
}

long long solve(int n, int k) {
    long long ans = 0;
    for (int i = 0; i <= n - k; i++) {
        long long term = C(n - k, i) * BigMod(n - k - i, n, MOD) % MOD;
        if (i % 2 == 0)
            ans = (ans + term) % MOD;
        else
            ans = (ans - term + MOD) % MOD;
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    Scan in;
    int t = 1;
    // t = in.nextInt();
    for (int qq = 1; qq <= t; qq++) {
        long long n, k;
        n = in.nextLong();
        k = in.nextLong();
        f[0] = 1;
        for (long long i = 1; i <= n; i++) {
            f[i] = (f[i - 1] * i) % MOD;
        }
        if (k >= n) {
            cout << 0 << "\n";
        } else if (k == 0) {
            cout << f[n] << "\n";
        } else {
            long long result = (2 * C((int)n, (int)(n - k)) % MOD) * solve((int)n, (int)k) % MOD;
            cout << result << "\n";
        }
    }
    return 0;
}

